begin;
create function pg_temp.s_id(n integer) returns uuid language sql immutable as $$select ('90000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.s_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.s_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected %',state;end$$;
create function pg_temp.s_command(n integer default 0) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.s_id(n+1),'expectedVersion',0,'entry',jsonb_build_object('id',pg_temp.s_id(n+2),'registrationId',pg_temp.s_id(95),'personId',pg_temp.s_id(50),'role','head','active',true))$$;
grant execute on function pg_temp.s_id(integer),pg_temp.s_assert(boolean,text),pg_temp.s_error(text,text),pg_temp.s_command(integer) to anon,authenticated;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.s_id(98)),(pg_temp.s_id(99));
insert into public.admin_access(user_id) values(pg_temp.s_id(98));
insert into public.championships(id,name) values(pg_temp.s_id(90),'Staff fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.s_id(91),pg_temp.s_id(90),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.s_id(92),pg_temp.s_id(91),'feminino','Adulto');
insert into public.teams(id,name) values(pg_temp.s_id(94),'Team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.s_id(95),pg_temp.s_id(92),pg_temp.s_id(94),'A'),(pg_temp.s_id(96),pg_temp.s_id(92),pg_temp.s_id(94),'B');
insert into public.persons(id,name) values(pg_temp.s_id(50),'Ana'),(pg_temp.s_id(51),'Bia'),(pg_temp.s_id(52),'Carla');
insert into public.coaches(person_id) values(pg_temp.s_id(50)),(pg_temp.s_id(51)),(pg_temp.s_id(52));
insert into private.athletes(person_id,sex) values(pg_temp.s_id(50),'female');
set local role anon;
select pg_temp.s_error('select public.list_staff(pg_temp.s_id(95))','42501');
set local role authenticated;
set local request.jwt.claim.sub='90000000-0000-4000-8000-000000000099';
select pg_temp.s_error('select public.save_staff_entry(pg_temp.s_command())','PT403');
set local request.jwt.claim.sub='90000000-0000-4000-8000-000000000098';
select pg_temp.s_error('delete from public.staff_entries','42501');
select public.save_staff_entry(pg_temp.s_command());
select public.save_staff_entry(pg_temp.s_command());
select public.save_staff_entry(jsonb_set(jsonb_set(pg_temp.s_command(10),'{entry,personId}',to_jsonb(pg_temp.s_id(51))),'{entry,role}','"assistant"'));
select pg_temp.s_assert(jsonb_array_length(public.list_staff(pg_temp.s_id(95))->'items')=2,'one head and one assistant retained');
select pg_temp.s_error($q$select public.save_staff_entry(jsonb_set(pg_temp.s_command(20),'{entry,personId}',to_jsonb(pg_temp.s_id(52))))$q$,'PT400');
select pg_temp.s_error($q$select public.save_staff_entry(jsonb_set(jsonb_set(jsonb_set(pg_temp.s_command(),'{commandId}',to_jsonb(pg_temp.s_id(60))),'{expectedVersion}','1'),'{entry,registrationId}',to_jsonb(pg_temp.s_id(96))))$q$,'PT400');
select pg_temp.s_error($q$select public.save_staff_entry(jsonb_set(pg_temp.s_command(),'{commandId}',to_jsonb(pg_temp.s_id(61))))$q$,'PT409');
-- Edits of an already linked person touch Recentes but not C1 metadata version.
create temp table s_before as select saved_at,version from public.championships where id=pg_temp.s_id(90);
select public.save_person(jsonb_build_object('commandId',pg_temp.s_id(80),'expectedVersion',1,'disputeId',null,'confirmHomonym',false,'person',(public.get_person(pg_temp.s_id(50))-'version'-'savedAt')||'{"nickname":"Aninha"}'::jsonb));
select pg_temp.s_assert((select c.saved_at>b.saved_at and c.version=b.version from public.championships c cross join s_before b where c.id=pg_temp.s_id(90)),'global person edit updates linked competition Recentes');
select pg_temp.s_assert((select count(*)=1 from private.athletes where person_id=pg_temp.s_id(50)),'athlete and coach share one person');
select public.save_staff_entry(jsonb_set(jsonb_set(jsonb_set(pg_temp.s_command(),'{commandId}',to_jsonb(pg_temp.s_id(62))),'{expectedVersion}','1'),'{entry,active}','false'));
select public.save_staff_entry(jsonb_set(pg_temp.s_command(20),'{entry,personId}',to_jsonb(pg_temp.s_id(52))));
select pg_temp.s_assert(jsonb_array_length(public.list_staff(pg_temp.s_id(95),false)->'items')=3,'previous coach remains historical');
select pg_temp.s_error($q$select public.save_staff_entry(jsonb_set(jsonb_set(pg_temp.s_command(),'{commandId}',to_jsonb(pg_temp.s_id(63))),'{expectedVersion}','2'))$q$,'PT400');
select pg_temp.s_assert(not ((public.get_staff_entry(pg_temp.s_id(12))->'person') ? 'athlete'),'staff projection excludes athlete private details');
select pg_temp.s_error('select * from private.staff_commands','42501');
reset role;
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.s_assert(public.get_staff_entry(pg_temp.s_id(2)) is null,'revocation hides staff');
select pg_temp.s_error('select public.save_staff_entry(pg_temp.s_command())','PT403');
reset role;
rollback;
